    if t is None {
        return None;
    }
    w = t spawn DescendantFlood(claimed={});
    out: list[str] = [];
    for n in w.found {
        if n != tag {
            out.append(n);
        }
    }
    return out;
}

def tag_project(tx: Taxonomy, project: str, tag: str) {
